cd /tmp/pw-check && cat > debug.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });
await page.goto('http://localhost:4173/');
await page.waitForTimeout(1500);
const info = await page.evaluate(() => {
  const h = document.querySelector('main h1');
  const cs = getComputedStyle(h);
  const r = h.getBoundingClientRect();
  const app = getComputedStyle(document.querySelector('.app'));
  return { rect: [r.x, r.y, r.width, r.height], display: cs.display, visibility: cs.visibility, color: cs.color, opacity: cs.opacity,
    appBg: app.backgroundColor, appDisplay: app.display, bodyClass: document.body.className,
    gravityLoaded: [...document.styleSheets].map(s => s.href).filter(Boolean), rootHTML: document.getElementById('root').innerHTML.slice(0, 200) };
});
console.log(JSON.stringify(info, null, 2));
await page.screenshot({ path: '/tmp/pw-check/debug.png' });
await browser.close();
EOF
LD_LIBRARY_PATH=$(cat /tmp/ldpath.txt) timeout 120 node debug.mjs 2>&1 | head -60

cd /tmp/pw-check && cat > debug2.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });
await page.goto('http://localhost:4173/');
await page.waitForTimeout(1000);
const info = await page.evaluate(() => {
  const h = document.querySelector('main h1');
  const cs = getComputedStyle(h);
  const body = getComputedStyle(document.body);
  const rootVars = getComputedStyle(document.body);
  const names = ['--g-text-header-1-font-size','--g-font-family-sans','--g-text-body-font-size-2','--g-color-text-primary','--g-spacing-base'];
  const vars = Object.fromEntries(names.map(n => [n, rootVars.getPropertyValue(n)]));
  const rules = [];
  for (const sheet of document.styleSheets) { try { for (const r of sheet.cssRules) { if (r.cssText.includes('g-text_variant_header-1')) rules.push(r.cssText.slice(0, 300)); } } catch {} }
  return { fontSize: cs.fontSize, lineHeight: cs.lineHeight, fontFamily: cs.fontFamily, bodyFont: body.fontFamily, vars, rules: rules.slice(0,3), sheetCount: document.styleSheets.length, cssRuleCount: [...document.styleSheets].map(s=>{try{return s.cssRules.length}catch{return 'x'}}) };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();
EOF
LD_LIBRARY_PATH=$(cat /tmp/ldpath.txt) timeout 120 node debug2.mjs 2>&1 | head -60; echo "--- built css head:"; grep -o "g-text_variant_header-1[^}]*}" /tmp/app-dist/assets/*.css | head -3; echo "--- fonts.css check:"; grep -c "@font-face" /home/sandbox/workspace/node_modules/@gravity-ui/uikit/build/esm/styles/styles.css 2>/dev/null; ls /home/sandbox/workspace/node_modules/@gravity-ui/uikit/styles/ 2>/dev/null

