cd /tmp/pw-check && cat > debug4.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });
await page.goto('http://localhost:4173/#/tasks');
await page.evaluate(() => localStorage.setItem('app-theme', 'dark'));
await page.reload();
await page.waitForSelector('main h1');
const info = await page.evaluate(() => {
  const pick = (sel) => { const el = document.querySelector(sel); if (!el) return null; const c = getComputedStyle(el); return { color: c.color, bg: c.backgroundColor, cls: el.className.slice(0,120) }; };
  return {
    body: document.body.className,
    navHome: pick('.app__nav a:not([aria-current])'),
    navActive: pick('.app__nav a[aria-current]'),
    textPrimaryVar: getComputedStyle(document.body).getPropertyValue('--g-color-text-primary'),
    textPrimaryAppVar: getComputedStyle(document.querySelector('.app')).getPropertyValue('--g-color-text-primary'),
    textBodyVar: getComputedStyle(document.querySelector('.app')).getPropertyValue('--g-color-text-dark-primary'),
    buttonTextVar: getComputedStyle(document.querySelector('.app__nav a:not([aria-current])')).getPropertyValue('--g-button-text-color'),
    flatRule: [...document.styleSheets].flatMap(s => { try { return [...s.cssRules] } catch { return [] } }).map(r => r.cssText).filter(t => t.includes('g-button_view_flat') && !t.includes('hover')).slice(0,4),
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();
EOF
FONTCONFIG_FILE=/tmp/fc/fonts.conf LD_LIBRARY_PATH=$(cat /tmp/ldpath.txt) timeout 120 node debug4.mjs 2>&1 | head -80

